<template><section><div class="toolbar implementation-tool-actions"><button v-if="mode!=='intake'" type="button" class="btn brand" :disabled="!ready||saving" @click="save">{{saving?'Salvando…':'Salvar processo'}}</button><span role="status">{{message}}</span></div><p class="muted">O processo salvo mantém os dados e as revisões. Os arquivos originais permanecem nesta sessão e precisam ser selecionados novamente após sair.</p><div ref="container" class="implementation-legacy"></div></section></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,onActivated} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {mountLegacy} from './legacy';import {runtime} from './runtime';
const props=defineProps<{mode:string}>(),container=ref<HTMLElement>(),saving=ref(false),message=ref(''),ready=ref(false),route=useRoute(),router=useRouter();let controller:any=null,closed=false,loadedProcess='',loadingProcess='';
async function start(){if(!container.value)return;try{controller=await mountLegacy(container.value,props.mode,{navigate:mode=>router.push('/planilhas/'+mode),handoff:(file,diagnosis)=>{(runtime() as any).handoff={file,diagnosis};void router.push('/planilhas/pre');}});if(closed){controller.destroy();return;}ready.value=true;await restore();}catch(e){if(!closed)message.value=(e as Error).message;}}
async function restore(){if(!controller)return;const rt:any=runtime();if(props.mode==='pre'&&rt.handoff){controller.start?.('pre',rt.handoff.file,rt.handoff.diagnosis);rt.handoff=null;}if(route.query.process){const id=String(route.query.process);if(id===loadedProcess||id===loadingProcess)return;loadingProcess=id;try{const result=await rt.json('/documents/'+encodeURIComponent(id)+'?account_id='+encodeURIComponent(rt.accountId));if(!closed&&loadingProcess===id){controller.restore?.(result.data.payload);rt.versions.set(id,result.data.version);controller.savedId=id;loadedProcess=id;message.value='Processo recuperado.';}}finally{if(loadingProcess===id)loadingProcess='';}}}
async function save(){if(!controller?.snapshot)return;saving.value=true;message.value='';try{const rt=runtime(),id=controller.savedId;const body={account_id:rt.accountId,expected_version:id?rt.versions.get(id)??0:0,kind:props.mode==='laudo'?'laudo':'import',body:{name:props.mode==='laudo'?'Leitura de laudos':'Planilhas · '+props.mode,mode:props.mode,purpose:props.mode==='laudo'?'reports':'history',payload:controller.snapshot()}};const result=await rt.json('/documents'+(id?'/'+id:''),body,id?'PUT':'POST');if(!closed){controller.savedId=result.data.id;rt.versions.set(result.data.id,result.data.version);message.value='Revisão '+result.data.version+' salva.';}}catch(e){if(!closed)message.value=(e as Error).message;}finally{if(!closed)saving.value=false;}}
onMounted(start);onActivated(()=>{if(controller)void restore();});onBeforeUnmount(()=>{closed=true;controller?.destroy();controller=null;});
</script>
